// Mock fleet inventory across three MDMs - swap for Jamf + Kandji/Iru + Intune APIs (the reconciliation platform pattern)
return [
  { json: { serial: 'C02XK1', user: 'dana@example.com', platform: 'macOS', mdm: 'Jamf', lastCheckinHrs: 4, osVersion: '15.6', targetOs: '15.6', fileVault: true, edrAgent: true, diskFreePct: 34 } },
  { json: { serial: 'C02XK2', user: 'marco@example.com', platform: 'macOS', mdm: 'Kandji', lastCheckinHrs: 190, osVersion: '15.4', targetOs: '15.6', fileVault: true, edrAgent: true, diskFreePct: 22 } },
  { json: { serial: 'WIN881', user: 'priya@example.com', platform: 'Windows', mdm: 'Intune', lastCheckinHrs: 9, osVersion: '11-24H2', targetOs: '11-24H2', fileVault: false, edrAgent: true, diskFreePct: 51 } },
  { json: { serial: 'WIN882', user: 'sam@example.com', platform: 'Windows', mdm: 'Intune', lastCheckinHrs: 30, osVersion: '11-23H2', targetOs: '11-24H2', fileVault: true, edrAgent: false, diskFreePct: 7 } }
];

// Posture checks per device. Severity mirrors blast radius: encryption and EDR are non-negotiables.
const out = [];
for (const item of $input.all()) {
  const d = item.json;
  const fails = [];
  if (!d.fileVault) fails.push({ check: 'disk encryption OFF', sev: 'CRITICAL', action: 'Escalate today: enable via MDM policy, verify key escrow' });
  if (!d.edrAgent) fails.push({ check: 'EDR agent missing', sev: 'CRITICAL', action: 'Push agent install now, confirm check-in within 24h' });
  if (d.lastCheckinHrs > 168) fails.push({ check: 'no MDM check-in 7d+', sev: 'WARNING', action: 'Ping user; if silent 48h, flag possible lost/off-network device in asset system' });
  if (d.osVersion !== d.targetOs) fails.push({ check: 'OS behind target (' + d.osVersion + ' vs ' + d.targetOs + ')', sev: 'NOTICE', action: 'Nudge user with update window; enforce via ring policy after grace period' });
  if (d.diskFreePct < 10) fails.push({ check: 'disk ' + d.diskFreePct + '% free', sev: 'NOTICE', action: 'Self-service cleanup nudge to user' });
  out.push({ json: { ...d, fails, healthy: fails.length === 0 } });
}
return out;

const devices = $input.all().map(i => i.json);
const healthy = devices.filter(d => d.healthy).length;
const score = Math.round(100 * healthy / devices.length);
const allFails = devices.flatMap(d => d.fails.map(f => ({ ...f, serial: d.serial, user: d.user, mdm: d.mdm })));
const bySev = { CRITICAL: [], WARNING: [], NOTICE: [] };
for (const f of allFails) bySev[f.sev].push(f);
let body = 'Fleet health: ' + score + '% fully healthy (' + healthy + '/' + devices.length + ' devices across Jamf, Kandji, Intune)\n';
for (const sev of ['CRITICAL', 'WARNING', 'NOTICE']) {
  if (!bySev[sev].length) continue;
  body += '\n== ' + sev + ' (' + bySev[sev].length + ') ==\n';
  for (const f of bySev[sev]) body += f.serial + ' (' + f.user + ', ' + f.mdm + '): ' + f.check + '\n  Next: ' + f.action + '\n';
}
body += '\nPrinciple: the fleet score is a trailing indicator; the CRITICAL list is today\'s to-do. Track the score weekly, work the list daily.';
return [{ json: { subject: 'Fleet health ' + score + '%: ' + bySev.CRITICAL.length + ' critical, ' + bySev.WARNING.length + ' warning', body } }];
